{
  "openapi": "3.0.3",
  "info": {
    "title": "Inventory API",
    "version": "1.0.0",
    "description": "Simple inventory management API used as a PoC fixture for G2 model validation."
  },
  "paths": {
    "/items": {
      "get": {
        "operationId": "listItems",
        "summary": "List all inventory items",
        "responses": {
          "200": {
            "description": "A list of items",
            "content": {
              "application/json": {
                "schema": {
                  "type": "array",
                  "items": {
                    "$ref": "#/components/schemas/Item"
                  }
                }
              }
            }
          }
        }
      },
      "post": {
        "operationId": "createItem",
        "summary": "Create a new inventory item",
        "requestBody": {
          "required": true,
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/ItemCreate"
              }
            }
          }
        },
        "responses": {
          "201": {
            "description": "Item created",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Item"
                }
              }
            }
          },
          "400": {
            "description": "Invalid input"
          }
        }
      }
    },
    "/items/{id}": {
      "get": {
        "operationId": "getItem",
        "summary": "Get a single inventory item by ID",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Item found",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/Item"
                }
              }
            }
          },
          "404": {
            "description": "Item not found"
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "Item": {
        "type": "object",
        "required": ["id", "name", "quantity"],
        "properties": {
          "id": {
            "type": "string",
            "description": "Unique identifier for the item"
          },
          "name": {
            "type": "string",
            "description": "Name of the inventory item"
          },
          "quantity": {
            "type": "integer",
            "minimum": 0,
            "description": "Current stock quantity"
          },
          "price": {
            "type": "number",
            "format": "double",
            "description": "Unit price in EUR"
          }
        }
      },
      "ItemCreate": {
        "type": "object",
        "required": ["name", "quantity"],
        "properties": {
          "name": {
            "type": "string",
            "description": "Name of the inventory item"
          },
          "quantity": {
            "type": "integer",
            "minimum": 0,
            "description": "Initial stock quantity"
          },
          "price": {
            "type": "number",
            "format": "double",
            "description": "Unit price in EUR"
          }
        }
      }
    }
  }
}

